const CSP = "default-src 'self'; script-src 'self' 'sha256-ZaJZxUqDODBv+rIoxexK6JvMnThAQ/FnQINFBKD7pkU='; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; form-action 'none'";

const assets = new Map();
for (const [path, item] of Object.entries(BUNDLED_ASSETS)) {
  const compressed = Buffer.from(item.gzipBase64, 'base64');
  const body = gunzipSync(compressed);
  const digest = createHash('sha256').update(body).digest('hex');
  if (digest !== item.sha256) throw new Error('Bundled asset checksum mismatch: ' + path);
  assets.set(path, {
    type: item.type, body, compressed,
    etag: '"' + digest + '"',
    gzipEtag: '"' + digest + '-gzip"',
  });
}
const headers = {
  'X-Site-Version': 'research-v2-2026-10-07',
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=()',
  'Content-Security-Policy': CSP,
};

function plain(req, res, code, message, extra = {}) {
  const body = Buffer.from(message + '\n');
  res.writeHead(code, { ...headers, 'Content-Type': 'text/plain; charset=utf-8',
    'Content-Length': body.length, 'Cache-Control': 'no-store', ...extra });
  res.end(req.method === 'HEAD' ? undefined : body);
}

function gzipAccepted(value) {
  return String(value || '').split(',').some(part => {
    const [encoding, ...params] = part.trim().split(';');
    const quality = params.find(p => /^\s*q\s*=/.test(p));
    return encoding.toLowerCase() === 'gzip' &&
      (!quality || Number(quality.split('=')[1]) > 0);
  });
}

const server = http.createServer({ maxHeaderSize: 16384 }, (req, res) => {
  if (!['GET', 'HEAD'].includes(req.method)) {
    req.resume();
    return plain(req, res, 405, 'Method not allowed', { Allow: 'GET, HEAD' });
  }
  let path;
  try {
    path = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
    if (/[\u0000-\u001f\u007f]/.test(path)) throw new Error('Invalid path');
  } catch (_) {
    return plain(req, res, 400, 'Bad request');
  }
  if (path === '/healthz') return plain(req, res, 200, 'ok');
  if (path === '/') path = '/index.html';
  if (path === '/research' || path === '/research/') return plain(req, res, 308, 'Redirecting', { Location: '/research.html' });

  let asset = assets.get(path);
  let status = 200;
  if (!asset) {
    asset = assets.get('/404.html');
    status = 404;
  }
  if (!asset) return plain(req, res, 404, 'Not found');

  const isPDF = asset.type === 'application/pdf';
  const useGzip = !isPDF && !req.headers.range && gzipAccepted(req.headers['accept-encoding']);
  let body = useGzip ? asset.compressed : asset.body;
  const etag = useGzip ? asset.gzipEtag : asset.etag;
  const responseHeaders = {
    ...headers, 'Content-Type': asset.type,
    'Cache-Control': status === 404 ? 'no-store' : path.startsWith('/assets/') ? 'public, max-age=3600' : 'no-cache',
    ETag: etag, Vary: 'Accept-Encoding',
  };
  if (useGzip) responseHeaders['Content-Encoding'] = 'gzip';
  if (isPDF && status === 200) {
    responseHeaders['Accept-Ranges'] = 'bytes';
    responseHeaders['Content-Disposition'] = 'inline; filename="Zhengjia-Lu-CV.pdf"';
  }
  const matches = String(req.headers['if-none-match'] || '').split(',').map(s => s.trim().replace(/^W\//, ''));
  if (status === 200 && (matches.includes(etag) || matches.includes('*'))) {
    res.writeHead(304, responseHeaders);
    return res.end();
  }
  if (isPDF && status === 200 && req.headers.range &&
      (!req.headers['if-range'] || req.headers['if-range'] === asset.etag)) {
    const range = /^bytes=(\d*)-(\d*)$/.exec(String(req.headers.range));
    if (range && (range[1] || range[2])) {
      const size = asset.body.length;
      let start = range[1] ? Number(range[1]) : Math.max(0, size - Number(range[2]));
      let end = range[1] ? (range[2] ? Number(range[2]) : size - 1) : size - 1;
      if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start > end || start >= size) {
        return plain(req, res, 416, 'Range not satisfiable', { 'Content-Range': 'bytes */' + size });
      }
      end = Math.min(end, size - 1);
      body = asset.body.subarray(start, end + 1);
      responseHeaders['Content-Range'] = `bytes ${start}-${end}/${size}`;
      status = 206;
    }
  }
  responseHeaders['Content-Length'] = body.length;
  res.writeHead(status, responseHeaders);
  res.end(req.method === 'HEAD' ? undefined : body);
});

const port = Number(process.env.PORT || 10000);
if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error('PORT must be an integer from 1 to 65535');
server.requestTimeout = 30000;
server.headersTimeout = 125000;
server.keepAliveTimeout = 120000;
server.timeout = 120000;
server.on('error', error => {
  console.error('Server failed:', error.message);
  process.exitCode = 1;
});
server.listen(port, '0.0.0.0', () => console.log('Academic website listening on port ' + port));
let stopping = false;
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => {
    if (stopping) return;
    stopping = true;
    server.close(() => process.exit(0));
    if (server.closeIdleConnections) server.closeIdleConnections();
    setTimeout(() => process.exit(0), 9000).unref();
  });
}
